import{_ as m,a0 as s,w as S,s as r,I as t,x as a,a1 as n,A as l,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"回顾 Steam Machines 与 SteamOS | LCTT x X-CMD","titleTemplate":false,"description":"回顾 Steam Machines 与 SteamOS | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"回顾 Steam Machines 与 SteamOS | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"回顾 Steam Machines 与 SteamOS | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20161110 User Editorial Steam Machines & SteamOS after a year in the wild","title":"回顾 Steam Machines 与 SteamOS","tag":"201710","desc":""},"relativePath":"201710/20161110 User Editorial Steam Machines & SteamOS after a year in the wild.md","filePath":"[post].md"}'),h={name:"201710/20161110 User Editorial Steam Machines & SteamOS after a year in the wild.md"};function p(d,e,M,v,V,u){const i=s("Link");return S(),r("div",null,[e[22]||(e[22]=t("h1",{id:"回顾-steam-machines-与-steamos",tabindex:"-1"},[a("回顾 Steam Machines 与 SteamOS "),t("a",{class:"header-anchor",href:"#回顾-steam-machines-与-steamos","aria-label":"Permalink to “回顾 Steam Machines 与 SteamOS”"},"​")],-1)),t("p",null,[e[1]||(e[1]=a("去年今日（LCTT 译注：本文发表于 2016 年），在非常符合 Valve 风格的跳票之后，大众迎来了 ",-1)),n(i,{href:"https://www.gamingonlinux.com/articles/steam-machines-steam-link-steam-controller-officially-released-steamos-sale.6201"},{default:l(()=>[...e[0]||(e[0]=[a("Steam Machines 的发布",-1)])]),_:1}),e[2]||(e[2]=a("。即使是在 Linux 桌面环境对于游戏的支持大步进步的今天，Steam Machines 作为一个平台依然没有飞跃，而 SteamOS 似乎也止步不前。这些由 Valve 发起的项目究竟怎么了？这些项目为何被发起，又是如何失败的？一些改进又是否曾有机会挽救这些项目的成败？",-1))]),e[23]||(e[23]=t("h3",{id:"行业环境",tabindex:"-1"},[a("行业环境 "),t("a",{class:"header-anchor",href:"#行业环境","aria-label":"Permalink to “行业环境”"},"​")],-1)),e[24]||(e[24]=t("p",null,"在 2012 年 Windows 8 发布的时候，微软像 iOS 与 Android 那样，为 Windows 集成了一个应用商店。在微软试图推广对触摸体验友好的界面时，为了更好的提供 “Metro” UI 语言指导下的沉浸式触摸体验，他们同时推出了一系列叫做 “WinRT” 的 API。然而为了能够使用这套 API，应用开发者们必须把应用程序通过 Windows 应用商城发布，并且正如其它应用商城那样，微软从中抽成 30%。对于 Valve 的 CEO，Gabe Newell (G 胖) 而言，这种限制发布平台和抽成行为是让人无法接受的，而且他前瞻地看到了微软利用行业龙头地位来推广 Windows 商店和 Metro 应用对于 Valve 潜在的危险，正如当年微软用 IE 浏览器击垮 Netscape 浏览器一样。",-1)),e[25]||(e[25]=t("p",null,"对于 Valve 来说，运行 Windows 的 PC 的优势在于任何人都可以不受操作系统和硬件方的限制运行各种软件。当像 Windows 这样的专有平台对像 Steam 这样的第三方软件限制越来越严格时，应用开发者们自然会想要寻找一个对任何人都更开放和自由的替代品，他们很自然的会想到 Linux 。Linux 本质上只是一套内核，但你可以轻易地使用 GNU 组件、Gnome 等软件在这套内核上开发出一个操作系统，比如 Ubuntu 就是这么来的。推行 Ubuntu 或者其他 Linux 发行版自然可以为 Valve 提供一个无拘无束的平台，以防止微软或者苹果变成 Valve 作为第三方平台之路上的的敌人，但 Linux 甚至给了 Valve 一个创造新的操作系统平台的机会。",-1)),e[26]||(e[26]=t("h3",{id:"概念化",tabindex:"-1"},[a("概念化 "),t("a",{class:"header-anchor",href:"#概念化","aria-label":"Permalink to “概念化”"},"​")],-1)),e[27]||(e[27]=t("p",null,"如果我们把 Steam Machines 叫做主机的话，Valve 当时似乎认定了主机平台是一个机会。为了迎合用户对于电视主机平台用户界面的审美期待，同时也为了让玩家更好地从稍远的距离上在电视上玩游戏，Valve 为 Steam 推出了 Big Picture 模式。Steam Machines 的核心要点是开放性；比方说所有的软件都被设计成可以脱离 Windows 工作，又比如说 Steam Machines 手柄的 CAD 图纸也被公布出来以便支持玩家二次创作。",-1)),e[28]||(e[28]=t("p",null,"原初计划中，Valve 打算设计一款官方的 Steam Machine 作为旗舰机型。但最终，这些机型只在 2013 年的时候作为原型机给与了部分测试者用于测试。Valve 后来也允许像戴尔这样的 OEM 厂商们制造 Steam Machines，并且也赋予了他们制定价格和配置规格的权利。有一家叫做 “Xi3” 的公司展示了他们设计的 Steam Machine 小型机型，那款机型小到可以放在手掌上，这一新闻创造了围绕 Steam Machines 的更多热烈讨论。最终，Valve 决定不自己设计制造 Steam Machines，而全权交给 OEM 合作厂商们。",-1)),e[29]||(e[29]=t("p",null,"这一过程中还有很多天马行空的创意被列入考量，比如在手柄上加入生物识别技术、眼球追踪以及动作控制等。在这些最初的想法里，陀螺仪被加入了 Steam Controller 手柄，HTC Vive 的手柄也有各种动作追踪仪器；这些想法可能最初都来源于 Steam 手柄的设计过程中。手柄最初还有些更激进的设计，比如在中心放置一块可定制化并且会随着游戏内容变化的触摸屏。但最后的最后，发布会上的手柄偏向保守了许多，但也有诸如双触摸板和内置软件等黑科技。Valve 也考虑过制作面向笔记本类型硬件的 Steam Machines 和 SteamOS。这个企划最终没有任何成果，但也许 “Smach Z” 手持游戏机会是发展的方向之一。",-1)),t("p",null,[e[4]||(e[4]=a("在 ",-1)),n(i,{href:"https://www.gamingonlinux.com/articles/valve-announces-steam-machines-you-can-win-one-too.2469"},{default:l(()=>[...e[3]||(e[3]=[a("2013 年九月",-1)])]),_:1}),e[5]||(e[5]=a("，Valve 对外界宣布了 Steam Machines 和 SteamOS， 并且预告会在 2014 年中发布。前述的 300 台原型机在当年 12 月分发给了测试者们，随后次年 1 月，又分发给了开发者们 2000 台原型机。SteamOS 也在那段时间分发给有 Linux 经验的测试者们试用。根据当时的测试反馈，Valve 最终决定把产品发布延期到 2015 年 11 月。",-1))]),e[30]||(e[30]=o("",38)),t("p",null,[e[7]||(e[7]=a("本文是被一位访客提交的，我们欢迎大家前来",-1)),n(i,{href:"https://www.gamingonlinux.com/submit-article/"},{default:l(()=>[...e[6]||(e[6]=[a("提交文章",-1)])]),_:1}),e[8]||(e[8]=a("。",-1))]),e[31]||(e[31]=t("hr",null,null,-1)),t("p",null,[e[10]||(e[10]=a("via: ",-1)),n(i,{href:"https://www.gamingonlinux.com/articles/user-editorial-steam-machines-steamos-after-a-year-in-the-wild.8474"},{default:l(()=>[...e[9]||(e[9]=[a("https://www.gamingonlinux.com/articles/user-editorial-steam-machines-steamos-after-a-year-in-the-wild.8474",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=a("作者：",-1)),n(i,{href:"https://www.gamingonlinux.com/profiles/5163"},{default:l(()=>[...e[11]||(e[11]=[a("calvin",-1)])]),_:1}),e[15]||(e[15]=a(" 译者：",-1)),n(i,{href:"https://github.com/Moelf"},{default:l(()=>[...e[12]||(e[12]=[a("Moelf",-1)])]),_:1}),e[16]||(e[16]=a(" 校对：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...e[13]||(e[13]=[a("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[17]||(e[17]=[a("LCTT",-1)])]),_:1}),e[20]||(e[20]=a(" 原创编译，",-1)),n(i,{href:"https://linux.cn/"},{default:l(()=>[...e[18]||(e[18]=[a("Linux中国",-1)])]),_:1}),e[21]||(e[21]=a(" 荣誉推出",-1))])])}const C=m(h,[["render",p]]);export{f as __pageData,C as default};
